  'previous.33': E('Temporal validation CSV', 'Уақыттық валидация CSV'),
  'previous.34': E('Frozen sources JSON', 'Бекітілген дереккөздер JSON'),
  'previous.35': E('Download and version register JSON', 'Жүктеу және нұсқалар тізілімі JSON'),
  'previous.36': E('Gap shares CSV', 'Олқылық үлестері CSV'),
